//! `AccountCore`: an account held in memory without an engine, for the steps that happen before
//! a record store exists or that the engine does not forward (creation's result, seed transfer,
//! recording due transitions, calls and links, moving). The reads it shares with the engine are
//! generated by `account_reads!`.
use super::action::{
    begin, next_owner, prf_results, signatures, signer_choice, AccountAction, Prepared,
};
use super::fault::AccountError;
use super::json::*;
use super::{guard, lock};
use colophon_core::v05::account::{
    Account, Changes, EpochSecret, Finished, Identity, Incoming, Standing,
};
use colophon_core::v05::encoding::{digest, strict_parse};
use colophon_core::v05::history::Objects;
use colophon_core::v05::records::HeldRecord;
use colophon_core::v05::slots::{OpeningInput, OpeningSecret};
use colophon_core::v05::vault::{EcdhOutput, PrfOutput};
use serde_json::{json, Value};
use std::sync::Mutex;

type R<T> = Result<T, AccountError>;

pub(crate) fn identity(text: &str) -> R<Identity> {
    let (kind, id) = text
        .split_once(':')
        .ok_or_else(|| AccountError::bad("identity is `controller:<id>` or `member:<id>`"))?;
    if id.len() != 32 || !id.bytes().all(|b| b.is_ascii_hexdigit() && !b.is_ascii_uppercase()) {
        return Err(AccountError::bad("identity names a 32-hex key ID"));
    }
    match kind {
        "controller" => Ok(Identity::Controller(id.into())),
        "member" => Ok(Identity::Member(id.into())),
        _ => Err(AccountError::bad(
            "identity is `controller:<id>` or `member:<id>`",
        )),
    }
}
pub(crate) fn objects(text: &str) -> R<Objects> {
    if text.is_empty() {
        return Ok(Objects::default());
    }
    let v = parse(text, "objects")?;
    obj(&v, "objects")?;
    Ok(Objects {
        entries: b64_list(&v, "entries")?,
        pending: b64_list(&v, "pending")?,
        heads: b64_list(&v, "heads")?,
        predecessor: b64_list(&v, "predecessor")?,
    })
}
pub(crate) fn records(text: &str) -> R<Vec<HeldRecord>> {
    if text.is_empty() {
        return Ok(Vec::new());
    }
    let v = parse(text, "records")?;
    let a = v
        .as_array()
        .ok_or_else(|| AccountError::bad("records must be an array"))?;
    if a.len() > MAX_LIST {
        return Err(AccountError::bound("too many records"));
    }
    a.iter()
        .map(|r| {
            Ok(HeldRecord {
                path: text_of(r, "path")?,
                bytes: b64(r, "bytes")?,
            })
        })
        .collect()
}
fn text_of(v: &Value, k: &str) -> R<String> {
    Ok(text(v, k)?.to_string())
}
pub(crate) fn changes_json(c: &Changes) -> R<String> {
    ser!(c)
}
pub(crate) fn denial_json(d: &colophon_core::model::Denial) -> Value {
    json!({"reason": d.reason, "detail": d.detail})
}
/// `(path, bytes)` of everything a finished action produced, in the order the core's
/// `record_paths` names them.
pub(crate) fn stores_of(f: &Finished) -> Vec<(String, Vec<u8>)> {
    let paths = f.record_paths();
    let mut bytes: Vec<Vec<u8>> = f.entries.iter().map(|(_, b)| b.clone()).collect();
    bytes.extend(f.pending.iter().cloned());
    bytes.extend(f.records.iter().map(|r| r.bytes.clone()));
    if paths.len() == bytes.len() {
        paths.into_iter().zip(bytes).collect()
    } else {
        Vec::new()
    }
}
pub(crate) fn finished_json(f: &Finished) -> R<Value> {
    Ok(json!({
        "entries": f.entries.iter().map(|(s, b)| json!({"seq": s, "bytes": enc(b)})).collect::<Vec<_>>(),
        "pending": bytes_list(&f.pending),
        "records": f.records.iter().map(|r| json!({"path": r.path, "bytes": enc(&r.bytes)})).collect::<Vec<_>>(),
        "artifact": f.artifact.as_ref().map(|a| enc(a)),
        "stores": stores(&stores_of(f)),
        "changes": ser_value!(f.changes)?,
        "info": {"name": f.info.name, "rekeyOwed": f.info.rekey_owed,
                 "owedNamespaces": f.info.owed_namespaces, "walkIncomplete": f.info.walk_incomplete},
    }))
}

fn body_of(env: &[u8]) -> R<Value> {
    let v = strict_parse(env)?;
    let body = decode(text(&v, "body")?, "body")?;
    Ok(strict_parse(&body)?)
}
/// Where every object and record an account holds is stored.
pub(crate) fn account_stores(a: &Account) -> R<Vec<(String, Vec<u8>)>> {
    let mut out = Vec::new();
    let o = a.objects();
    for e in &o.entries {
        let seq = body_of(e)?
            .get("seq")
            .and_then(Value::as_u64)
            .ok_or_else(|| AccountError::internal("an entry without a seq"))?;
        out.push((format!("authority/{seq:08}.json"), e.clone()));
    }
    for e in &o.predecessor {
        let seq = body_of(e)?
            .get("seq")
            .and_then(Value::as_u64)
            .ok_or_else(|| AccountError::internal("a predecessor entry without a seq"))?;
        out.push((format!("predecessor/authority/{seq:08}.json"), e.clone()));
    }
    for p in &o.pending {
        let raw = decode(text(&strict_parse(p)?, "body")?, "body")?;
        let b = body_of(p)?;
        let path = match b.get("protocol").and_then(Value::as_str) {
            Some("colophon/veto/5") => format!("vetoes/{}.json", digest(&raw)),
            Some("colophon/receipt/5") => format!(
                "receipts/{}/{}.receipt.json",
                text(&b, "object")?,
                text(&b, "by")?
            ),
            _ => format!("transitions/{}.json", digest(&raw)),
        };
        out.push((path, p.clone()));
    }
    for h in &o.heads {
        let b = body_of(h)?;
        out.push((format!("heads/{}.json", text(&b, "by")?), h.clone()));
    }
    for r in a.records() {
        out.push((r.path.clone(), r.bytes.clone()));
    }
    Ok(out)
}

pub(crate) fn opening_inputs_json(i: &[OpeningInput]) -> Value {
    Value::Array(
        i.iter()
            .map(|i| match i {
                OpeningInput::Ecdh { controller, enc: e } => {
                    json!({"type": "ecdh", "controller": controller, "enc": enc(e)})
                }
                OpeningInput::Prf { controller, salt } => {
                    json!({"type": "prf", "controller": controller, "salt": enc(salt)})
                }
            })
            .collect(),
    )
}
/// `[{"type":"ecdh","secret"}|{"type":"prf","output"}]`: consumed, never returned.
pub(crate) fn opening_secrets(text_in: &str) -> R<Vec<OpeningSecret>> {
    let v = parse(text_in, "secrets")?;
    let a = v
        .as_array()
        .ok_or_else(|| AccountError::bad("secrets must be an array"))?;
    if a.len() > MAX_NAMES {
        return Err(AccountError::bound("too many secrets"));
    }
    a.iter()
        .map(|s| match text(s, "type")? {
            "ecdh" => Ok(OpeningSecret::Ecdh(EcdhOutput::from_host(&b64(
                s, "secret",
            )?)?)),
            "prf" => Ok(OpeningSecret::Prf(PrfOutput::from_host(&b64(s, "output")?)?)),
            _ => Err(AccountError::bad("a secret is `ecdh` or `prf`")),
        })
        .collect()
}
pub(crate) fn slots_json(a: &Account) -> R<Value> {
    Ok(Value::Array(
        a.slots()?
            .into_iter()
            .map(|s| {
                json!({"index": s.index, "kind": s.kind, "label": s.label,
                    "controllers": s.controllers.iter().map(|(i, l)| json!({"id": i, "label": l})).collect::<Vec<_>>()})
            })
            .collect(),
    ))
}
pub(crate) fn agreements_json(a: &Account) -> Value {
    Value::Array(
        a.begin_unlock_epochs()
            .into_iter()
            .map(|s| {
                json!({"namespace": s.namespace, "epoch": s.epoch, "recipient": s.recipient,
                    "recipientPoint": enc(&s.recipient_point), "peer": enc(&s.peer)})
            })
            .collect(),
    )
}
/// `[{"namespace","epoch","shared"}]` answers to the account's own agreements: each is matched
/// to the account's current request, so a made-up step is refused.
pub(crate) fn epoch_secrets(a: &Account, text_in: &str) -> R<Vec<EpochSecret>> {
    let v = parse(text_in, "answers")?;
    let arr = v
        .as_array()
        .ok_or_else(|| AccountError::bad("answers must be an array"))?;
    if arr.len() > MAX_LIST {
        return Err(AccountError::bound("too many answers"));
    }
    let want = a.begin_unlock_epochs();
    arr.iter()
        .map(|r| {
            let ns = text(r, "namespace")?;
            let epoch = uint(r, "epoch")?;
            let step = want
                .iter()
                .find(|w| w.namespace == ns && w.epoch == epoch)
                .ok_or_else(|| AccountError::bad("an answer for a share not asked for"))?
                .clone();
            Ok(EpochSecret {
                step,
                shared: EcdhOutput::from_host(&b64(r, "shared")?)?,
            })
        })
        .collect()
}
pub(crate) fn standing_json(s: &Standing) -> R<String> {
    ser!(s)
}

/// The reads an account answers the same way inside an engine or on its own.
/// `$with` is a method `fn(&self, FnOnce(&Account) -> R<T>) -> R<T>`.
macro_rules! account_reads {
    ($ty:ty) => {
        #[cfg_attr(feature = "native05", uniffi::export)]
        #[cfg_attr(feature = "web05", wasm_bindgen::prelude::wasm_bindgen)]
        impl $ty {
            /// The account ID (64 hex).
            pub fn id(&self) -> Result<String, AccountError> {
                self.with_account(|a| Ok(a.id().as_str().to_string()))
            }
            /// This session's identity: `controller:<id>` or `member:<id>`.
            pub fn identity(&self) -> Result<String, AccountError> {
                self.with_account(|a| {
                    Ok(match a.identity() {
                        Identity::Controller(i) => format!("controller:{i}"),
                        Identity::Member(i) => format!("member:{i}"),
                    })
                })
            }
            /// The verifier's verdict on the history: `{seq, code, stopSeq, detail, rollback}`.
            pub fn status(&self) -> Result<String, AccountError> {
                self.with_account(|a| ser!(a.status()))
            }
            /// The head of the verified branch: `{"seq", "digest"}`.
            pub fn head(&self) -> Result<String, AccountError> {
                self.with_account(|a| {
                    let (s, d) = a.head();
                    to_string(&json!({"seq": s, "digest": d}))
                })
            }
            /// Controllers, as JSON (no key bytes beyond public descriptors' IDs and forms).
            pub fn controllers(&self) -> Result<String, AccountError> {
                self.with_account(|a| ser!(a.controllers()))
            }
            /// Homes the account names.
            pub fn homes(&self) -> Result<String, AccountError> {
                self.with_account(|a| ser!(a.homes()))
            }
            /// The effective policy.
            pub fn policy(&self) -> Result<String, AccountError> {
                self.with_account(|a| ser!(a.policy()))
            }
            /// Pending transitions, each with its due time, vetoes and receipts.
            pub fn pending(&self) -> Result<String, AccountError> {
                self.with_account(|a| ser!(a.pending()))
            }
            /// Shares members are owed (§9.4).
            pub fn owed_shares(&self) -> Result<String, AccountError> {
                self.with_account(|a| ser!(a.owed_shares()))
            }
            /// What a person must be shown (§17.5): unseen pending transitions, activations no
            /// local key signed, owed shares, controllers without a slot, a retiring vault, no
            /// home. `shown_transitions` and `local_keys` are JSON arrays of strings.
            pub fn notices(
                &self,
                shown_seq: u64,
                shown_transitions: String,
                local_keys: String,
            ) -> Result<String, AccountError> {
                let shown: std::collections::BTreeSet<String> =
                    names_of(&parse(&shown_transitions, "shown transitions")?, "shown transitions")?
                        .into_iter()
                        .collect();
                let keys = names_of(&parse(&local_keys, "local keys")?, "local keys")?;
                self.with_account(|a| ser!(a.notices(shown_seq, &shown, &keys)))
            }
            /// Open proposals (§11.6) of a namespace.
            pub fn proposals(&self, namespace: String) -> Result<String, AccountError> {
                self.with_account(|a| ser!(a.proposals(&namespace)))
            }
            /// The tools this session can call.
            pub fn tools(&self) -> Result<String, AccountError> {
                self.with_account(|a| {
                    to_string(&Value::Array(
                        a.tools()
                            .into_iter()
                            .map(|t| serde_json::to_value(&t).unwrap_or(Value::Null))
                            .collect(),
                    ))
                })
            }
            /// The slots of the current vault, as a chooser shows them.
            pub fn slots(&self) -> Result<String, AccountError> {
                self.with_account(|a| to_string(&slots_json(a)?))
            }
            /// Whether the vault seed is held (a controller is unlocked).
            pub fn is_unlocked(&self) -> Result<bool, AccountError> {
                self.with_account(|a| Ok(a.is_unlocked()))
            }
            /// The ECDH work a member's host does to open its shares: JSON array.
            pub fn begin_unlock_epochs(&self) -> Result<String, AccountError> {
                self.with_account(|a| to_string(&agreements_json(a)))
            }
            /// The ECDH work for one slot: JSON array of `ecdh` and `prf` inputs.
            pub fn begin_unlock_slot(&self, index: u64) -> Result<String, AccountError> {
                self.with_account(|a| {
                    let i = usize::try_from(index)
                        .map_err(|_| AccountError::bound("slot index"))?;
                    to_string(&opening_inputs_json(&a.begin_unlock_slot(i)?))
                })
            }
            /// Fork candidates `[(seq, digest, digest)]` a resolve may choose between.
            pub fn fork_candidates(&self) -> Result<String, AccountError> {
                self.with_account(|a| {
                    to_string(&Value::Array(
                        a.fork_candidates()
                            .into_iter()
                            .map(|(s, x, y)| json!([s, x, y]))
                            .collect(),
                    ))
                })
            }
            /// Controllers (IDs) that together meet the rule `need` (`member`, `rekey`,
            /// `control`, `recovery`, `keyring_add`, `veto`) from those the host can sign with.
            pub fn suggest_signers(
                &self,
                available: String,
                need: String,
            ) -> Result<String, AccountError> {
                let have = names_of(&parse(&available, "available")?, "available")?;
                let need = signer_choice(&need)?;
                self.with_account(|a| to_string(&json!(a.suggest_signers(&have, need)?)))
            }
            /// The latest epoch of a namespace.
            pub fn latest_epoch(&self, namespace: String) -> Result<u64, AccountError> {
                self.with_account(|a| Ok(a.latest_epoch(&namespace)))
            }
            /// Why a namespace is not readable now (`{"reason","detail"}`), or empty.
            pub fn write_denial(&self, namespace: String) -> Result<String, AccountError> {
                self.with_account(|a| match a.write_denial(&namespace) {
                    Some(d) => to_string(&denial_json(&d)),
                    None => Ok(String::new()),
                })
            }
            /// Everything the account holds, as `(path, bytes)` JSON, for the host to store.
            pub fn stores(&self) -> Result<String, AccountError> {
                self.with_account(|a| to_string(&stores(&account_stores(a)?)))
            }
        }
    };
}
pub(crate) use account_reads;

/// An account in memory without an engine.
#[cfg_attr(feature = "native05", derive(uniffi::Object))]
#[cfg_attr(feature = "web05", wasm_bindgen::prelude::wasm_bindgen)]
pub struct AccountCore {
    pub(crate) acc: Mutex<Account>,
    pub(crate) owner: u64,
}
impl AccountCore {
    pub(crate) fn from(a: Account) -> Self {
        Self {
            acc: Mutex::new(a),
            owner: next_owner(),
        }
    }
    fn with_account<T>(&self, f: impl FnOnce(&Account) -> R<T>) -> R<T> {
        guard(|| f(&*lock(&self.acc)?))
    }
    fn open_inner(
        objs: String,
        recs: String,
        stored: Vec<u8>,
        mut key: Vec<u8>,
        identity_text: String,
        now_ms: i64,
    ) -> R<Self> {
        guard(|| {
            let o = objects(&objs)?;
            let r = records(&recs)?;
            bounded(&stored, 1 << 30, "stored state")?;
            let me = identity(&identity_text)?;
            let k: Option<[u8; 32]> = if stored.is_empty() {
                None
            } else {
                Some(fixed::<32>(&key, "the sealed-state key")?)
            };
            key.fill(0);
            let a = Account::open(
                o,
                r,
                k.as_ref().map(|k| (stored.as_slice(), k)),
                me,
                now_ms,
            )?;
            Ok(Self::from(a))
        })
    }
}
account_reads!(AccountCore);

#[cfg_attr(feature = "native05", uniffi::export)]
#[cfg_attr(feature = "web05", wasm_bindgen::prelude::wasm_bindgen)]
impl AccountCore {
    /// What this session is in the verified history: `controller`, `member` or `unknown`.
    pub fn me(&self) -> Result<String, AccountError> {
        self.with_account(|a| standing_json(&a.me()))
    }
    /// Members, with their terms and standing.
    pub fn members(&self) -> Result<String, AccountError> {
        self.with_account(|a| ser!(a.members()))
    }
    /// The ledger of what happened, newest last.
    pub fn ledger(&self) -> Result<String, AccountError> {
        self.with_account(|a| ser!(a.ledger()))
    }
    /// Why `namespace` is not readable now (`{"reason","detail"}`), or an empty string.
    pub fn access(&self, namespace: String) -> Result<String, AccountError> {
        self.with_account(|a| match a.access(&namespace) {
            Some(d) => to_string(&denial_json(&d)),
            None => Ok(String::new()),
        })
    }
    /// A namespace's folded view: `{"ok":true,"value":{...}}` or `{"ok":false,"reason",...}`.
    pub fn view(&self, namespace: String) -> Result<String, AccountError> {
        self.with_account(|a| ser!(a.view(&namespace)?))
    }
    /// A named domain query; `args` is JSON.
    pub fn query(
        &self,
        namespace: String,
        name: String,
        args: String,
    ) -> Result<String, AccountError> {
        let args = parse_or_null(&args, "args")?;
        self.with_account(|a| ser!(a.query(&namespace, &name, args)?))
    }
    /// The account's revision of a namespace's fold.
    pub fn revision(&self, namespace: String) -> Result<u64, AccountError> {
        self.with_account(|a| Ok(a.revision(&namespace)))
    }
    /// The clock the account holds.
    pub fn now_ms(&self) -> Result<i64, AccountError> {
        self.with_account(|a| Ok(a.now_ms()))
    }
    /// Forget the vault seed. A controller reads and writes nothing until it unlocks again.
    pub fn lock(&self) -> Result<(), AccountError> {
        guard(|| {
            lock(&self.acc)?.lock();
            Ok(())
        })
    }
    /// Open a slot with the host's secrets and open every epoch the seed reaches. `secrets` is
    /// the JSON `[{"type":"ecdh","secret"}|{"type":"prf","output"}]` in input order; they are
    /// consumed and never returned. Returns the changes.
    pub fn finish_unlock_slot(&self, index: u64, secrets: String) -> Result<String, AccountError> {
        guard(|| {
            let i = usize::try_from(index).map_err(|_| AccountError::bound("slot index"))?;
            let s = opening_secrets(&secrets)?;
            changes_json(&lock(&self.acc)?.finish_unlock_slot(i, &s)?)
        })
    }
    /// A member opens its shares: `answers` is `[{"namespace","epoch","shared"}]`.
    pub fn finish_unlock_epochs(&self, answers: String) -> Result<String, AccountError> {
        guard(|| {
            let mut a = lock(&self.acc)?;
            let s = epoch_secrets(&a, &answers)?;
            changes_json(&a.finish_unlock_epochs(s)?)
        })
    }
    /// Merge objects and records the host holds (a fetch, a store). Returns the changes.
    pub fn merge(
        &self,
        objects_json: String,
        records_json: String,
        now_ms: i64,
    ) -> Result<String, AccountError> {
        guard(|| {
            let inc = Incoming {
                objects: objects(&objects_json)?,
                records: records(&records_json)?,
            };
            changes_json(&lock(&self.acc)?.merge(inc, now_ms)?)
        })
    }
    /// Move the clock forward; time decides what is held, due, expired and suspended.
    pub fn advance(&self, now_ms: i64) -> Result<String, AccountError> {
        guard(|| changes_json(&lock(&self.acc)?.advance(now_ms)?))
    }
    /// Narrow the namespaces this session reads (a JSON array of names).
    pub fn set_read_scope(&self, namespaces: String) -> Result<String, AccountError> {
        guard(|| {
            let n = names_of(&parse(&namespaces, "namespaces")?, "namespaces")?;
            changes_json(&lock(&self.acc)?.set_read_scope(n)?)
        })
    }
    /// Record every determined `activate`, `vetoed` and `final`, all or nothing. Returns the
    /// finished recordings (JSON array) for the host to store and publish.
    pub fn record_due(&self) -> Result<String, AccountError> {
        guard(|| {
            let done = lock(&self.acc)?.record_due()?;
            let v: R<Vec<Value>> = done.iter().map(finished_json).collect();
            to_string(&Value::Array(v?))
        })
    }
    /// The verifier's persisted state, sealed under `key` (32 bytes, device-held, used for
    /// this call only) with `nonce_seed` (32 fresh bytes), for the host to store atomically.
    pub fn export_persisted(
        &self,
        mut key: Vec<u8>,
        mut nonce_seed: Vec<u8>,
    ) -> Result<Vec<u8>, AccountError> {
        let r = guard(|| {
            let k = fixed::<32>(&key, "the sealed-state key")?;
            let n = fixed::<32>(&nonce_seed, "the nonce seed")?;
            Ok(lock(&self.acc)?.export_persisted(&k, n)?)
        });
        key.fill(0);
        nonce_seed.fill(0);
        r
    }
}

#[cfg(feature = "native05")]
#[uniffi::export]
impl AccountCore {
    /// Open an account from its objects (`{"entries","pending","heads","predecessor"}`, each an
    /// array of base64) and records (`[{"path","bytes"}]`) as `identity` at `now_ms`. `stored`
    /// is the sealed verifier state from `export_persisted` and `key` the 32-byte device-held
    /// key it was sealed under; with no stored state pass empty for both. The key is used for
    /// this call and not kept. A state that does not verify is ignored and the history replays.
    #[uniffi::constructor]
    pub fn open(
        objects: String,
        records: String,
        stored: Vec<u8>,
        key: Vec<u8>,
        identity: String,
        now_ms: i64,
    ) -> Result<std::sync::Arc<Self>, AccountError> {
        Self::open_inner(objects, records, stored, key, identity, now_ms).map(std::sync::Arc::new)
    }
    /// Prepare an action. `spec` is JSON naming the action and its arguments (see
    /// `docs/bindings-05.md`); `entropy` is the fresh 32-byte parts the action takes.
    pub fn begin(
        &self,
        spec: String,
        entropy: Vec<u8>,
    ) -> Result<std::sync::Arc<AccountAction>, AccountError> {
        self.begin_inner(spec, entropy).map(std::sync::Arc::new)
    }
    /// Give the PRF assertions an action asked for; the bodies are then built.
    pub fn provide_prf(
        &self,
        action: std::sync::Arc<AccountAction>,
        results: String,
    ) -> Result<(), AccountError> {
        self.provide_prf_inner(&action, results)
    }
    /// Finish a prepared action with the host's signatures (JSON, in step order). The core
    /// assembles the bytes from its own state, verifies them, and only then changes. Returns
    /// the finished action as JSON, with `stores` to persist. A failed finish consumes the
    /// action; prepare again with fresh entropy.
    pub fn finish(
        &self,
        action: std::sync::Arc<AccountAction>,
        signatures: String,
    ) -> Result<String, AccountError> {
        self.finish_inner(&action, signatures)
    }
}

#[cfg(feature = "web05")]
#[wasm_bindgen::prelude::wasm_bindgen]
impl AccountCore {
    pub fn open(
        objects: String,
        records: String,
        stored: Vec<u8>,
        key: Vec<u8>,
        identity: String,
        now_ms: i64,
    ) -> Result<AccountCore, AccountError> {
        Self::open_inner(objects, records, stored, key, identity, now_ms)
    }
    pub fn begin(&self, spec: String, entropy: Vec<u8>) -> Result<AccountAction, AccountError> {
        self.begin_inner(spec, entropy)
    }
    pub fn provide_prf(&self, action: &AccountAction, results: String) -> Result<(), AccountError> {
        self.provide_prf_inner(action, results)
    }
    pub fn finish(&self, action: &AccountAction, signatures: String) -> Result<String, AccountError> {
        self.finish_inner(action, signatures)
    }
}
impl AccountCore {
    fn begin_inner(&self, spec: String, mut entropy: Vec<u8>) -> R<AccountAction> {
        guard(|| {
            let spec = parse(&spec, "the action")?;
            let a = lock(&self.acc)?;
            let (kind, p) = begin(&a, None, &spec, &mut entropy)?;
            Ok(match p {
                Prepared::Action(p) => AccountAction::ready(p, self.owner, &kind),
                Prepared::Denied(d) => AccountAction::denied(d, self.owner, &kind),
            })
        })
    }
    fn provide_prf_inner(&self, action: &AccountAction, results: String) -> R<()> {
        guard(|| {
            let r = prf_results(&results)?;
            let p = action.take(self.owner)?;
            let a = lock(&self.acc)?;
            let next = a.provide_prf(p, r)?;
            action.put_back(next)
        })
    }
    fn finish_inner(&self, action: &AccountAction, signatures_json: String) -> R<String> {
        guard(|| {
            let sigs = signatures(&signatures_json)?;
            let p = action.take(self.owner)?;
            let f = lock(&self.acc)?.finish(p, sigs)?;
            to_string(&finished_json(&f)?)
        })
    }
}
